<?php $this->layout('default'); use Moves\Services\ContactMessages as M; use Moves\Services\CmsAuth; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = M::listing($filters, V::queryPage()); $counts = M::counts(); $reply = CmsAuth::can($admin, 'tickets.reply'); ?>
<?= V::tabs([['/mensagens', 'Todas', array_sum($counts), $filters['status'] === ''], ['?status=new', 'Novas', $counts['new'], $filters['status'] === 'new'], ['?status=answered', 'Respondidas', $counts['answered'], $filters['status'] === 'answered']], 'Situação') ?>
<section class="cms-list"><?= V::listHead('Mensagens recebidas', $result['total'] . ' registro(s)', V::searchForm('Nome, e-mail ou assunto')) ?><?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma mensagem recebida.') ?><?php else: ?><div class="cms-log"><?php foreach ($result['rows'] as $m): ?><details><summary><?= V::badge($m['status'] === 'new' ? 'pending' : 'active', M::STATUS[$m['status']] ?? '') ?><span class="cms-log-main"><strong><?= V::e($m['subject']) ?></strong><small><?= V::e($m['name']) ?> · <?= V::e($m['email']) ?> · <?= V::date($m['created_at']) ?></small></span></summary><div class="cms-message-body"><p><?= nl2br(V::e($m['message'])) ?></p><dl class="cms-dl"><dt>E-mail</dt><dd><a href="mailto:<?= V::e($m['email']) ?>"><?= V::e($m['email']) ?></a></dd><dt>Telefone</dt><dd><?= V::e($m['phone'] !== '' ? $m['phone'] : '—') ?></dd><dt>WhatsApp</dt><dd><?= $m['whatsapp_ok'] ? 'Aceita resposta por WhatsApp' : 'Não autorizou' ?></dd></dl><?php if ($reply): ?><p><?= $m['status'] === 'new' ? V::actionButton('contact-status', 'Marcar como respondida', ['id' => $m['id'], 'answered' => 1], 'cms-btn-primary') : V::actionButton('contact-status', 'Reabrir', ['id' => $m['id'], 'answered' => 0]) ?></p><?php endif; ?></div></details><?php endforeach; ?></div><?= V::pager($result) ?><?php endif; ?></section>
